using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var document = new StringBuilder();

        AppendHeader(document, invoice, account);
        var (net, vat) = AppendInvoiceLines(document, invoice);
        AppendTotals(document, net, vat, account);
        AppendPaymentTerms(document, account);

        return document.ToString();
    }

    private static void AppendHeader(StringBuilder document, Invoice invoice, Account account)
    {
        document.AppendLine($"INVOICE {invoice.Number}");
        if (account.Name.Length > 0)
            document.AppendLine(account.Name);

        switch (account.Kind)
        {
            case AccountKind.Business:
                document.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                document.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                document.AppendLine("Consumer");
                break;
        }
    }

    private static (decimal Net, decimal Vat) AppendInvoiceLines(
        StringBuilder document,
        Invoice invoice)
    {
        decimal net = 0m;
        decimal vat = 0m;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                continue;

            var lineVat = line.NetAmount * line.VatRate;
            AppendInvoiceLine(document, line.Description, line.NetAmount, line.VatRate, lineVat);
            net += line.NetAmount;
            vat += lineVat;
        }

        return (net, vat);
    }

    private static void AppendInvoiceLine(
        StringBuilder document,
        string description,
        decimal netAmount,
        decimal vatRate,
        decimal vatAmount)
    {
        if (vatRate == 0m)
            document.AppendLine($"{description} {netAmount} (zero-rated)");
        else if (vatRate >= 0.2m)
            document.AppendLine($"{description} {netAmount} (std {vatAmount})");
        else
            document.AppendLine($"{description} {netAmount} (reduced {vatAmount})");

        if (description.Length > 40)
            document.AppendLine("  (description truncated)");
    }

    private static void AppendTotals(
        StringBuilder document,
        decimal net,
        decimal vat,
        Account account)
    {
        var discount = CalculateDiscount(net, account.Kind);
        var gross = net + vat - discount;
        if (gross < 0m)
            gross = 0m;

        document.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");
    }

    private static decimal CalculateDiscount(decimal net, AccountKind accountKind)
    {
        if (net > 1000m && accountKind == AccountKind.Business)
            return net * 0.05m;
        if (net > 5000m)
            return net * 0.10m;
        return 0m;
    }

    private static void AppendPaymentTerms(StringBuilder document, Account account)
    {
        if (account.Kind == AccountKind.Government)
            document.AppendLine("Remit within 30 days");
        else
            document.AppendLine("Remit within 14 days");
    }
}
